const panel=document.createElement('aside');panel.className='culture-panel';panel.setAttribute('aria-label','试验步骤与机理');panel.innerHTML='<div class="c-eyebrow" id="c-eyebrow"></div><h2 id="c-heading"></h2><div class="c-chain" id="c-chain"></div><div id="c-operations" class="c-operations" role="group" aria-label="本步操作"></div><ol id="c-points"></ol><div id="c-live" class="c-live" aria-live="polite"></div><div class="c-weigh-adjust" id="c-weigh-adjust" hidden><label for="c-grain-moisture">籽粒含水率 <output id="c-grain-moisture-value">14%</output><input id="c-grain-moisture" type="range" min="10" max="25" value="14" aria-label="籽粒含水率"></label></div><div id="c-results"></div><details id="c-recipe"><summary>配方与本处理用量</summary><div id="c-recipe-body"></div></details><details><summary>试验依据与边界</summary><p>依据本地《植物营养研究法电子书》第一章的土培、溶液培养与砂砾培养技术。苗期模拟数据采用 28 天终点，成熟收获为独立操作演示；处理浓度和观测值是教学设定，动画不是实测生长或输液动力学。</p><a href="https://github.com/Lidong-Huang/plant-nutrition-lab/blob/main/docs/磷效应培养试验.md" target="_blank" rel="noopener">完整步骤、配方与教材对应 ↗</a></details><div class="c-siblings"><a href="https://lidong-huang.github.io/plant-nutrition-lab/lessons/soil-culture.html">土培</a><a href="https://lidong-huang.github.io/plant-nutrition-lab/lessons/sand-culture.html">砂培</a><a href="https://lidong-huang.github.io/plant-nutrition-lab/lessons/hydro-culture.html">水培</a></div>';document.querySelector('.stage').append(panel);
